void current_wgl(const graphics::GlContextNativeIdentity&i){check(i.owner_thread&&i.context==reinterpret_cast<std::uintptr_t>(wglGetCurrentContext())&&i.dc==reinterpret_cast<std::uintptr_t>(wglGetCurrentDC())&&i.window==reinterpret_cast<std::uintptr_t>(WindowFromDC(reinterpret_cast<HDC>(i.dc))),"Oracle refuses foreign current WGL without switching");}
std::string escaped(std::string_view text){std::string s="\"";for(unsigned char c:text){if(c=='"'||c=='\\'){s+='\\';s+=c;}else if(c<32){char b[7]{};std::snprintf(b,sizeof(b),"\\u%04x",c);s+=b;}else s+=c;}return s+'"';}
std::string digest_float(const std::vector<float>&v){return runtime::identify_bytes(std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>(v.data()),v.size()*4)).sha256;}
void binary(const std::filesystem::path&p,std::span<const std::uint8_t>b){std::ofstream f(p,std::ios::binary);check(f.is_open()&&static_cast<bool>(f.write(reinterpret_cast<const char*>(b.data()),static_cast<std::streamsize>(b.size()))),"Failed isolated oracle evidence write");}
